-- RLS helper (no recursion, not exposed via RPC)
create schema if not exists private;
create function private.has_role(p_org uuid, p_roles text[]) returns boolean
language sql stable security definer set search_path = ''
as $$ select exists (select 1 from public.memberships m where m.org_id = p_org and m.user_id = (select auth.uid()) and m.role = any(p_roles)) $$;
grant usage on schema private to authenticated;
grant execute on function private.has_role(uuid, text[]) to authenticated;

