## Next 16: src/proxy.ts (file `src/proxy.ts`, export `proxy` — `middleware` is deprecated)
```ts
import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";

export async function proxy(request: NextRequest) {
  let response = NextResponse.next({ request });
  const supabase = createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!, {
    cookies: {
      getAll() { return request.cookies.getAll(); },
      setAll(cookiesToSet, headers) {
        cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value));
        response = NextResponse.next({ request });
        cookiesToSet.forEach(({ name, value, options }) => response.cookies.set(name, value, options));
        Object.entries(headers ?? {}).forEach(([k, v]) => response.headers.set(k, v)); // no-cache headers
      },
    },
  });
  await supabase.auth.getUser(); // refresh only; NO redirect -> API routes return their own 401
  return response;
}
export const config = {
  matcher: ["/((?!api/webhooks|_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)"],
};
```

## src/lib/supabase/server.ts
```ts
import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
export async function createClient() {
  const cookieStore = await cookies();
  return createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!, {
    cookies: {
      getAll() { return cookieStore.getAll(); },
      setAll(cookiesToSet) {
        try { cookiesToSet.forEach(({ name, value, options }) => cookieStore.set(name, value, options)); }
        catch { /* Server Component: proxy refreshes */ }
      },
    },
  });
}
```
src/app/api/me/route.ts: `const { data: { user } } = await (await createClient()).auth.getUser(); if (!user) return NextResponse.json({ error: "unauthenticated" }, { status: 401 });`
Verified: curl /api/me → 401 (not 307); with cookie `sb-127-auth-token=base64-<base64url(JSON session)>` → 200.

## vitest.config.mts + tests/global-setup.ts
```ts
// vitest.config.mts
import { defineConfig } from "vitest/config";
import nextEnv from "@next/env";
nextEnv.loadEnvConfig(process.cwd());
export default defineConfig({ resolve: { tsconfigPaths: true }, test: {
  environment: "node", include: ["tests/**/*.test.ts"], globalSetup: ["tests/global-setup.ts"],
  testTimeout: 30_000, hookTimeout: 180_000 } });
```
```ts
// tests/global-setup.ts
import { spawn, type ChildProcess } from "node:child_process";
const PORT = 3100, BASE = `http://localhost:${PORT}`;
let child: ChildProcess | undefined;
const up = () => fetch(`${BASE}/api/me`, { signal: AbortSignal.timeout(2000) }).then(() => true, () => false);
export async function setup() {
  process.env.TEST_BASE_URL = BASE;            // visible in test workers
  if (await up()) return;
  child = spawn("npx", ["next", "dev", "-p", String(PORT)], { stdio: "ignore", detached: true, env: { ...process.env } });
  for (const end = Date.now() + 120_000; Date.now() < end; await new Promise((r) => setTimeout(r, 1000)))
    if (await up()) return;
  throw new Error(`next dev did not come up on ${PORT}`);
}
export async function teardown() { if (child?.pid) try { process.kill(-child.pid, "SIGTERM"); } catch {} } // kill process group
```
