#!/usr/bin/env bash
# DB reset under an EXCLUSIVE lock: waits for running tests/probes (shared lock holders) to finish,
# and blocks new ones until the reset is done. Run from ./app.
set -euo pipefail
exec flock -x /tmp/ezy-db.lock npx supabase db reset "$@"
#!/usr/bin/env bash
# Run a command that uses the shared local DB (tests, probes) under a SHARED lock,
# so db-reset.sh never runs in the middle of it. Many shared holders can run at once.
# Usage (from ./app): bash ../scripts/with-db.sh npx vitest run tests/rls
set -euo pipefail
exec flock -s /tmp/ezy-db.lock "$@"

